"""The second variable-size worker's share of the e2e bridges (codegen/e2e_bridge.py imports it).

codegen/e2e_bridge.py owns the templates, the shared support modules (e2e_load, e2e_cap, e2e_emit,
e2e_ulist) and the manifest; this module only adds per-name entries and any new shared module:

  VDEC_VIEWS[X]   = {'view': 'RT.v_X', 'imports': [...], 'text': ...}   (ii)/(iii): the view lemma vv
  VROOT_SHAPES[X] = f(R, X) -> text                                     (iv): the rebuild from rep
  VENC_SHAPES[X]  = f(R, X) -> text                                     (i)
  SUPPORT_OUT     = {'e2e_<name>.bend': text}                           new shared modules
  VENC_PREMISE[X] = '...'                                               (i)'s premise text in the manifest

X is the generated name (api_map.json), R the readable one (names.py). A name counts as bridged in the
manifest's variable_size section once it has all three; see e2e_bridge's DataColumnsByRootIdentifier
entries for the pattern. Texts may import ../types/fulu_obj.bend as T: e2e_bridge rewires them.

The decode template reads from the name's decode facade: the decoder (T.<fn>), the object type
(Maybe<&1, ..>; override with VDEC_VIEWS[X]['otype']), the schema (Spec or GS), and whether OBJ / VAL
take the depth (OBJ(d, t, n)); it calls the view lemma with decode_accept's own hypotheses:
  vv(+d, +t, +n, +pf: perfect(d, t), +hd: d < bound, +hn: to_nat(n) <= quad(pow2(d)), +hchk: CHK(t, n) == True)
    -> {view(OBJ(..)) == VAL(..)}
"""

VDEC_VIEWS = {}
VROOT_SHAPES = {}
VENC_SHAPES = {}
SUPPORT_OUT = {}
VENC_PREMISE = {}


# ---- byte lists ----

# (iv) of a bare byte list (the object is O.Words; its root law and validity lemma live in the
# name's big_root_ / big_gvalid_ modules, over rep = LO.rep_bl). The words are rebuilt from wfl's
# witnesses (both cases) so the view is over copyable t, N.
def vroot_bytelist(R, X):
    OW = 'O.Words{FD.array__thaw(U32, t), N}'
    RX = lambda o: f'D.bytes(Pair.snd(O.Words, D.Digest, Pair.snd(B.Buf, O.Words & D.Digest, {R}_h.{X}_hash_tree_root(h, {o}))))'
    G = lambda o: f'{{Some{{{RX(o)}}} == API.hash_tree_root(Spec.{X}(), S.BytesValue{{WO.wview({o})}}) : Maybe<&2, +List<U32>>}}'
    imps = ['import Base', 'import ../END_TO_END.bend as E2E', 'import ../src/model.bend as API', 'import ../src/buffer.bend as B',
            'import ../src/digest.bend as D', 'import ../src/obj.bend as O', f'import ../types/{R}_hashtreeroot_generated.bend as {R}_h',
            'import ../types/schema.bend as S', 'import ../spec/fulu_schemas.bend as Spec', 'import ../proofs/type_validator_soundness.bend as VS',
            'import ../proofs/compact/found.bend as FD', 'import ../proofs/obj/words_obj.bend as WO', 'import ../proofs/obj/list_obj.bend as LO',
            f'import ../proofs/obj/big_root_{X}.bend as BR', f'import ../proofs/obj/big_gvalid_{X}.bend as GV', 'import ./e2e_support.bend as E']
    return '\n'.join(imps) + f"""

# GENERATED by codegen/e2e_bridge.py (codegen/e2e_var_b.py). Do not edit.
# {R} (variable size, a byte list): the object API's root is END_TO_END's hash_tree_root, for every
# object the root law represents (LO.rep_bl: its words in a perfect tree of depth below 32, its length
# within the limit).

def rt1(h: B.Buf, +t: FD.array__Tree<U32>, +N: U32, +rep: LO.rep_bl({OW}, Spec.{X}())) -> {G(OW)}:
  E.root_legal(Spec.{X}(), S.BytesValue{{WO.wview({OW})}}, VS.public_sound(Spec.{X}(), {{==}}), {RX(OW)},
    GV.{X}_root_valid({OW}, Spec.{X}(), {{==}}, rep), BR.{X}_root_correct(h, {OW}, Spec.{X}(), {{==}}, rep))

# the object as rep's witnesses name it
def rt2(h: B.Buf, -o: O.Words, +rep: LO.rep_bl(o, Spec.{X}()), +t: FD.array__Tree<U32>, +N: U32,
    +eo: {{o == {OW} : O.Words}}) -> {G('o')}:
  %Equal.sym(O.Words, o, {OW}, eo) : {G('_')}
  rt1(h, t, N, FD.logic__subst(O.Words, z => LO.rep_bl(z, Spec.{X}()), o, {OW}, eo, rep))

# (iv)
def {R}_e2e_root(h: B.Buf, -o: O.Words, +rep: LO.rep_bl(o, Spec.{X}())) -> {G('o')}:
  (+wf, +hl) = rep
  match wf:
    case Inl{{w}}:
      (+t, w1) = w
      (+dw, w2) = w1
      (+N, w3) = w2
      (+eo, w4) = w3
      rt2(h, o, rep, t, N, eo)
    case Inr{{w}}:
      (+t, w1) = w
      (+dw, w2) = w1
      (+N, w3) = w2
      (+q, w4) = w3
      (+r, w5) = w4
      (+eo, w6) = w5
      rt2(h, o, rep, t, N, eo)
"""



# The byte-list view (shared): the words a byte-list reader copies out of a buffer (vua_ct's CT at
# any byte offset) view as the window's bytes.


# (ii)/(iii) of a bare byte list: the reader's words at offset 0 (the codec's OBJ(d, t, n) =
# O.Words{thaw(CT(d, t, 0, n, DZ(n))), n}) view as VAL's bytes WX(t, 0, n) (e2e_blist.bview).
def vdec_bytelist(X, bound):
    return {'view': 'vbl',
            'imports': ['import ../proofs/obj/words_obj.bend as WO', 'import ./e2e_blist.bend as BL'],
            'text': f'''# ---- the view of a decoded object is the codec law's value ----

def vbl(o: O.Words) -> S.Value: S.BytesValue{{WO.wview(o)}}

def vv(+d: Nat, +t: FD.array__Tree<U32>, +n: U32, +pf: {{FD.array__perfect(U32, d, t) == True{{}} : Bool}}, +hd: {{Nat.is_lt(d, {'@BD@' if bound is None else str(bound) + 'n'}) == True{{}} : Bool}},
    +hn: {{Nat.is_le(U32.to_nat(n), A.quad(FD.spec_common__pow2(d))) == True{{}} : Bool}}, +hchk: {{DC.CHK(t, n) == True{{}} : Bool}}) -> {{vbl(DC.OBJ(d, t, n)) == DC.VAL(t, n) : S.Value}}:
  Equal.cong(+List<U32>, S.Value, z => S.BytesValue{{z}}, WO.wview(O.Words{{FD.array__thaw(U32, BL.CW(d, t, 0, n)), n}}), BL.WX0(t, n), BL.bview(d, t, 0, n, 0n, {{==}}, hd, hn, pf))

'''}





