            f'  +ec{sx} = Equal.trans(Nat, 1n+{q}, O.chunks_of({N}), {C}n, Equal.sym(Nat, O.chunks_of({N}), 1n+{q}, cc{sx}), FD.nat__eq_from_is_eq(O.chunks_of({N}), {C}n, nn{sx}))',
